// 全Workerの結果を集約してサマリーを作る
const all = $input.all();
const missionCtx = $('Quest 1: ミッション設定').item.json;

const newsItems  = all.filter(i => i.json.title && i.json.summary).slice(0, 3);
const videoItems = all.filter(i => i.json.video_title).slice(0, 3);

const newsSummary = newsItems.length
  ? newsItems.map(i => `- [${i.json.score}点] ${i.json.title}`).join('\n')
  : '(データなし)';

const videoSummary = videoItems.length
  ? videoItems.map(i => `- [${i.json.score}点] ${i.json.video_title} / フック: ${i.json.hook}`).join('\n')
  : '(データなし)';

return [{
  json: {
    mission:       missionCtx.mission,
    date:          missionCtx.date,
    news_summary:  newsSummary,
    video_summary: videoSummary,
    total_items:   all.length
  }
}];

const cmdOutput = $input.item.json.output?.[0]?.content?.[0]?.text || '';
const agg       = $('結果集約').item.json;

const get = (label) => {
  const m = cmdOutput.match(new RegExp(label + '[:：]\\s*([\\s\\S]+?)(?=\\n[^\\n]+[:：]|$)'));
  return m ? m[1].trim() : '(取得失敗)';
};

const topInfo   = get('注目情報');
const priority  = get('優先workflow');
const actions   = get('推奨アクション');

const report = [
  '# AI帝国 日次司令レポート',
  `日時: ${agg.date}`,
  '',
  '## 司令AIの判断',
  `**注目情報:** ${topInfo}`,
  `**優先workflow:** ${priority}`,
  '',
  '## 推奨アクション',
  actions,
  '',
  '## 収集データサマリー',
  '### 重要ニュース',
  agg.news_summary,
  '',
  '### 動画ネタ候補',
  agg.video_summary,
  '',
  `総収集件数: ${agg.total_items}件`
].join('\n');

return [{
  json: {
    date:           agg.date,
    top_info:       topInfo,
    priority_wf:    priority,
    actions:        actions,
    full_report:    report,
    total_items:    agg.total_items
  }
}];

